(7495512, 1193934, 68504, '<td valign="top">best use of imagination.</td>', 'best use of imagination.', '2017-01-30 00:39:25.000000', NULL, 0),
(7495513, 1193815, 30861, '<td valign="top">I expected a WHOLE lot better out of this, percentile-wise.  It really resonated with me in a sort of hard-edged, color-field, Gene Davis or Frank Stella sort of way. I was your 9. It''s a very luminous and fulfilling image.</td>', 'I expected a WHOLE lot better out of this, percentile-wise.  It really resonated with me in a sort of hard-edged, color-field, Gene Davis or Frank Stella sort of way. I was your 9. It''s a very luminous and fulfilling image.', '2017-01-30 00:40:25.000000', NULL, 0),
(7495516, 1193900, 68504, '<td valign="top">inviting lines, surprising depth.</td>', 'inviting lines, surprising depth.', '2017-01-30 00:41:10.000000', NULL, 0),
