(7495518, 1193689, 68504, '<td valign="top">good tones and texture.</td>', 'good tones and texture.', '2017-01-30 00:45:33.000000', NULL, 0),
(7495519, 1194012, 30861, '<td valign="top">You got clobbered for being "not abstract" but I don''t really agree with that. I was your lone 8. This is, for me, a very powerful image, fabulous light and detail, great sense of solidity and foreboding. For me, "abstraction" doesn''t HAVE to be "unrecognizable" at all, and my own entry in this challenge is analogous to yours in that it''s clearly recognizable as what it is, but it plays with massing and color to be other-than-simple-recording. Admittedly, neither of us was especially "expressionist", and we paid the price for that, you more than me, but so it goes. VERY cool shot and as an architectural photographer I really appreciate what you''ve done here.</td>', 'You got clobbered for being "not abstract" but I don''t really agree with that. I was your lone 8. This is, for me, a very powerful image, fabulous light and detail, great sense of solidity and foreboding. For me, "abstraction" doesn''t HAVE to be "unrecognizable" at all, and my own entry in this challenge is analogous to yours in that it''s clearly recognizable as what it is, but it plays with massing and color to be other-than-simple-recording. Admittedly, neither of us was especially "expressionist", and we paid the price for that, you more than me, but so it goes. VERY cool shot and as an architectural photographer I really appreciate what you''ve done here.', '2017-01-30 00:46:44.000000', NULL, 0),
(7495520, 1193862, 68504, '<td valign="top">love the roadside thingies.</td>', 'love the roadside thingies.', '2017-01-30 00:50:20.000000', NULL, 0),
